import pandas as pd

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for f in files:
    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.xls'):
            df = pd.read_excel(f, nrows=20, engine='xlrd')
        else:
            df = pd.read_excel(f, nrows=20, engine='openpyxl')
        print(df)
        print("\n")
    except Exception as e:
        print(f"Error reading {f}: {e}")

